using System;
using System.Drawing;
using System.Windows.Forms;
namespace Downfield {
public partial class GameForm {
 bool controllerBindings,capturing;string controlsBack="settings",controlsNotice="SELECT AN ACTION TO CHANGE IT";int captureAction,capturePrior;bool bindingRelease;
 int ControlsCount {get{return (controllerBindings?ControlBindings.PadActions.Length+1:ControlBindings.Actions.Length)+4;}}
 void OpenControls(string back){controlsBack=back;capturing=false;input.Clear();Open("bindings");}
 bool CaptureControlKey(Keys key){if(screen!="bindings"||!capturing)return false;if(key==Keys.Escape){capturing=false;controlsNotice="CANCELLED";}else if(!controllerBindings){controlsNotice=input.Bindings.BindKey(captureAction,key);capturing=false;input.Clear();}return true;}
 void TickBindings(){if(bindingRelease){if(input.RawButtons==0&&input.KeysDown.Count==0){bindingRelease=false;input.Clear();}return;}if(capturing){if(controllerBindings){int pressed=input.RawButtons&~capturePrior;capturePrior=input.RawButtons;if(pressed!=0){int one=pressed&-pressed;input.Bindings.BindPad(ControlBindings.PadActions[captureAction],one);capturing=false;controlsNotice="SAVED / CONFLICTING BUTTON SWAPPED";bindingRelease=true;input.Clear();}}if(input.KeysDown.Contains(Keys.Escape)){capturing=false;input.Clear();}return;}int direction=input.Pressed(Input.Down)||input.MoveZ<-.55f?1:input.Pressed(Input.Up)||input.MoveZ>.55f?-1:0;if(navTime<=0&&direction!=0){selection=(selection+direction+ControlsCount)%ControlsCount;navTime=.2f;}if(input.Pressed(Input.B)||input.PausePressed){Open(controlsBack);return;}if(input.Pressed(Input.A))ActivateBindings();}
 void ActivateBindings(){int count=controllerBindings?ControlBindings.PadActions.Length+1:ControlBindings.Actions.Length;if(selection==0){controllerBindings=!controllerBindings;selection=0;controlsNotice="SELECT AN ACTION TO CHANGE IT";return;}if(selection==count+1){input.Bindings=new ControlBindings();input.Bindings.Save();controlsNotice="DEFAULTS RESTORED";}else if(selection==count+2){returnScreen="bindings";Open("help");}else if(selection==count+3)Open(controlsBack);else if(controllerBindings&&selection==count){input.Bindings.SwapSticks=!input.Bindings.SwapSticks;input.Bindings.Save();}else{captureAction=selection-1;capturing=true;capturePrior=input.RawButtons;controlsNotice=controllerBindings?"PRESS NEW BUTTON OR TRIGGER / ESC CANCEL":"PRESS NEW KEY / ESC CANCEL";input.Clear();}}
 void DrawBindings(){FrontHeader("CONTROLS / REMAP");string mode=controllerBindings?"CONTROLLER":"KEYBOARD";Rect(40,168,1200,47,selection==0?TeamPrimary:Ink);TextAt("DEVICE: "+mode+"   < SWITCH >",60,183,14,Gold);HitArea(40,168,1200,47,0);int count=controllerBindings?ControlBindings.PadActions.Length+1:ControlBindings.Actions.Length;int first=selection>0&&selection<=count?(selection-1)/8*8:0;for(int i=first;i<Math.Min(first+8,count);i++){float y=231+(i-first)*50;bool chosen=selection==i+1;Rect(40,y,1200,44,chosen?Color.FromArgb(65,93,98):Color.FromArgb(36,44,58));string label=controllerBindings?i==count-1?"MOVE / SKILL STICKS":ControlBindings.PadLabels[i]:ControlBindings.Actions[i];string value=controllerBindings?i==count-1?(input.Bindings.SwapSticks?"RS MOVE / LS SKILLS":"LS MOVE / RS SKILLS"):input.ButtonLabel(ControlBindings.PadActions[i]):input.ActionLabel(i);TextAt(label,60,y+15,12,White);TextAt(capturing&&chosen?"PRESS INPUT...":value,840,y+15,12,chosen?Gold:Mint);HitArea(40,y,1200,44,i+1);}TextAt(controlsNotice,40,650,11,Mint);string[] buttons={"RESET DEFAULTS","HOW TO PLAY","BACK"};for(int n=0;n<3;n++){int index=count+1+n;float x=40+n*407;Rect(x,691,390,51,selection==index?TeamPrimary:Color.FromArgb(36,44,58));TextAt(buttons[n],x+20,709,14,selection==index?Gold:White);HitArea(x,691,390,51,index);}TextAt("ENTER / ESC ALWAYS WORK IN MENUS. SHARED BUTTONS KEEP MADDEN CONTEXTS.",40,136,10,Muted);}
